package in.anumati.platform.incentive; import in.anumati.platform.regulatory.RegulatorySource; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="incentive_schemes") public class IncentiveScheme {@Id private UUID id; @Column(nullable=false,unique=true,length=80) private String code; @Column(nullable=false,length=250) private String name; @Column(nullable=false,length=200) private String authority; @Column(name="benefit_summary",nullable=false,length=1500) private String benefitSummary; @Column(name="application_url",length=1000) private String applicationUrl; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="source_id",nullable=false) private RegulatorySource source; @Column(nullable=false) private boolean active; @Column(nullable=false) private Instant createdAt; protected IncentiveScheme(){} public IncentiveScheme(String code,String name,String authority,String benefit,String url,RegulatorySource source,boolean active){id=UUID.randomUUID();this.code=code;this.name=name;this.authority=authority;benefitSummary=benefit;applicationUrl=url;this.source=source;this.active=active;createdAt=Instant.now();} public UUID getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getAuthority(){return authority;}public String getBenefitSummary(){return benefitSummary;}public String getApplicationUrl(){return applicationUrl;}public RegulatorySource getSource(){return source;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}}
